#!/usr/bin/env bash
# Resolve packages and retain the exact lockfile generated by pub get when the
# committed lockfile does not match pubspec.yaml. This is diagnostic only:
# it never edits dependency constraints or silently commits the new lock.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT"

flutter pub get

REPORT_DIR="${KELIVO_CI_REPORT_DIR:-$ROOT/build-report}"
mkdir -p "$REPORT_DIR"

if git diff --quiet -- pubspec.lock; then
  echo "pubspec.lock remained unchanged after flutter pub get."
  exit 0
fi

cp pubspec.lock "$REPORT_DIR/resolved-pubspec.lock"
git diff --binary -- pubspec.lock > "$REPORT_DIR/pubspec-lock-diff.patch"

cat <<'NOTICE'
::warning::flutter pub get changed the checked-in pubspec.lock. The resolved lockfile and diff were retained in the build-report artifact. Review and commit the lockfile intentionally after checking compatibility.
NOTICE

echo "Resolved lockfile: $REPORT_DIR/resolved-pubspec.lock ($(wc -l < "$REPORT_DIR/resolved-pubspec.lock") lines)"
echo "Lockfile diff: $REPORT_DIR/pubspec-lock-diff.patch ($(wc -c < "$REPORT_DIR/pubspec-lock-diff.patch") bytes)"
